/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const deps_of = new Map()
  for (const k of costs.keys()) deps_of.set(k, new Set())
  for (const [name, ...ds] of deps) {
    for (const x of [name, ...ds]) if (!costs.has(x)) throw new Fail(`error: unknown task ${x}`)
    for (const d of ds) deps_of.get(name).add(d)
  }
  const names = [...costs.keys()].sort(cmp)
  const adj = new Map(names.map((k) => [k, [...deps_of.get(k)].sort(cmp)]))
  return { costs, names, adj }
}

function checkCycle({ names, adj }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of adj.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v))
        cyc.push(v)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

function times(g) {
  const { costs, names, adj } = g
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const go = (u) => {
    if (finish.has(u)) return
    let s = 0n
    let d = 0
    for (const v of adj.get(u)) {
      go(v)
      if (finish.get(v) > s) s = finish.get(v)
      if (depth.get(v) + 1 > d) d = depth.get(v) + 1
    }
    start.set(u, s)
    finish.set(u, s + costs.get(u))
    depth.set(u, d)
  }
  for (const k of names) go(k)
  let total = 0n
  for (const k of names) if (finish.get(k) > total) total = finish.get(k)
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const { costs, names, adj } = g
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of adj.get(k)) rev.get(d).push(k)
  const prio = new Map()
  const calc = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of rev.get(u)) {
      const p = calc(v)
      if (p > best) best = p
    }
    prio.set(u, best + costs.get(u))
    return prio.get(u)
  }
  // iterative-safe enough for typical sizes; compute in order
  for (const k of names) calc(k)
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(names)
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const k of pending) {
        if (!adj.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (pick === null || prio.get(k) > prio.get(pick) || (prio.get(k) === prio.get(pick) && k < pick)) pick = k
      }
      if (pick === null) break
      pending.delete(pick)
      const f = t + costs.get(pick)
      fin.set(pick, f)
      freeAt[w] = f
      ran[w].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return ran.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main() {
  const args = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers = 0
  if (args[0] === 'waves' || args[0] === 'explain') {
    if (args.length !== 1) throw new Fail(usage)
  } else if (args[0] === 'pack') {
    if (args.length !== 2) throw new Fail(usage)
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else {
    throw new Fail(usage)
  }
  const g = parse(readFileSync(0, 'utf8'))
  checkCycle(g)
  let out = ''
  if (args[0] === 'pack') {
    out = pack(g, workers)
  } else {
    const r = times(g)
    if (args[0] === 'waves') {
      const waves = []
      for (const k of g.names) (waves[r.depth.get(k)] ??= []).push(k)
      waves.forEach((ws, i) => {
        out += `wave ${i}: ${ws.join(' ')}\n`
      })
    } else {
      for (const k of g.names) out += `${k} start=${r.start.get(k)} finish=${r.finish.get(k)} depth=${r.depth.get(k)}\n`
    }
    out += `total ${r.total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
"}

